:root{--ink:#102c30;--paper:#f5f0e3;--cream:#fffbf2;--teal:#217f77;--coral:#b7523c;--line:#b8c9bd;--gold:#e4a841}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font-family:Georgia,serif}button{font:inherit;cursor:pointer}a{color:inherit}.wrap{max-width:1150px;margin:auto;padding:0 22px}.top{background:#102c30;color:#f4e9d4;padding:15px 0;border-bottom:3px solid var(--gold)}.top .wrap{display:flex;justify-content:space-between;align-items:center;gap:12px}.brand{font-family:'Courier New',monospace;font-size:11px;letter-spacing:.13em;text-decoration:none;text-transform:uppercase}.top small{font-size:11px;letter-spacing:.11em;color:#b3cac3;text-align:right}.hero{background:#102c30;color:var(--cream);overflow:hidden;position:relative}.hero:after{content:'';position:absolute;inset:0;background:radial-gradient(circle at 95% 95%,#41847755,transparent 45%);pointer-events:none}.hero-inner{display:grid;grid-template-columns:1fr 1.05fr;gap:5%;align-items:center;min-height:440px;padding-top:44px;padding-bottom:54px;position:relative;z-index:1}.eyebrow{font-family:'Courier New',monospace;font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--gold);margin:0 0 22px}.hero h1{font-family:Georgia,serif;font-weight:800;font-size:clamp(55px,7.6vw,105px);line-height:.93;letter-spacing:-.055em;margin:0 0 25px}.hero h1 em{font-weight:600;color:#92dbb9}.hero p{max-width:470px;line-height:1.6;font-size:17px;color:#d4ded6}.art{margin:0;position:relative;transform:rotate(1.5deg);box-shadow:17px 18px 0 #071a1c,0 0 0 6px #d1a35a;background:#236b67}.art img{width:100%;height:330px;object-fit:cover;display:block}.art figcaption{font:10px 'Courier New',monospace;letter-spacing:.08em;text-transform:uppercase;background:var(--gold);color:var(--ink);padding:9px 12px;position:absolute;right:0;bottom:0}.intro{border-bottom:1px solid var(--line);padding:24px 0}.intro .wrap{display:flex;justify-content:space-between;align-items: