tion:all .2s}.toggles button[data-side="0"].chosen{background:var(--teal);color:#fff;border-color:var(--teal)}.toggles button[data-side="1"].chosen{background:var(--coral);color:#fff;border-color:var(--coral)}.toggles button:focus-visible,.action:focus-visible{outline:3px solid var(--gold);outline-offset:2px}.lanes{display:grid;grid-template-columns:1fr 1fr;gap:12px}.lane{border:1px solid var(--line);min-height:210px;padding:13px;background:#f4faf5}.lane:nth-child(2){background:#fcf2e9}.lane h4{margin:0 0 4px;font:600 18px Georgia,serif}.lane:first-child h4{color:var(--teal)}.lane:nth-child(2) h4{color:var(--coral)}.lane small{font-size:11px;color:#526962}.lane ol{margin:14px 0 0;padding:0;list-style:none}.lane li{font:11px/1.5 'Courier New',monospace;padding:6px 0;border-top:1px dashed #b4c2b8;overflow-wrap:anywhere}.lane .empty{color:#8c9990;font-style:italic}.controls{display:flex;gap:11px;align-items:center;flex-wrap:wrap;margin-top:25px}.action{border:2px solid var(--ink);background:var(--gold);padding:12px 21px;font-weight:700;box-shadow:3px 3px 0 var(--ink)}.action:hover{transform:translate(2px,2px);box-shadow:1px 1px 0 var(--ink)}.action:disabled{opacity:.5;cursor:not-allowed}.secondary{background:transparent;box-shadow:none}.feedback{font-size:14px;line-height:1.5;min-height:25px}.insight{margin-top:23px;border-left:5px solid var(--teal);background:#e3eee6;padding:19px 23px;line-height:1.6}.insight[hidden]{display:none}.insight strong{font-family:Georgia,serif;font-size:23px}.footer{background:#102c30;color:#d9e8d8;padding:36px 0;font-size:14px;line-height:1.7}.footer a{color:#f2c374}.footer .wrap{display:flex;justify-content:space-between;gap:30px;flex-wrap:wrap}.footer p{margin:0}.grain{background-image:repeating-linear-gradient(0deg,transparent 0,transparent 4px,#15292706 5px)}@media(max-width:820px){.hero-inner{grid-template-columns:1fr;padding-top:40px}.hero h1{font-size:clamp(57px,12vw,90px)}.art img{height:260px}.desk{grid-template-columns:1fr}.intro .wrap{align-items:start;flex-direction:column}.game{padding-top:38px}}@media(max-width:490px){.wrap{padding:0 16px}.panel{padding:14px}.lanes{gap:7px}.lane{padding:10px;min-height:180px}.card{padding:9px;gap:6px}.card code{font-size:10px}.toggles button{width:31px;height:31px}.progress strong{font-size:19px}.hero p{font-size:15px}.art img{height:220px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{transition:none!important;animation:none!important;scroll-behavior:auto!important}}
