<section class="hero"><div class="wrap hero-inner"><div><p class="eyebrow">The case of the double-duty function</p><h1>Split the<br><em>Method.</em></h1><p>One function has been doing two jobs. Trace its decisions, route each instruction to the right responsibility, and watch the knots come undone.</p></div><figure class="art"><img src="split-the-method-switchboard.webp" alt="An illustrated vintage switchboard with a tangled central cable splitting into two tidy circuits"><figcaption>Exhibit A · The branching problem</figcaption></figure></div></section>
<section class="intro grain"><div class="wrap"><p><strong>How to play:</strong> Tap <strong>A</strong> or <strong>B</strong> beside every line. The same line can look different depending on its job: think about which responsibility it serves, not just the variables it mentions. Then run the tests.</p><span class="pill">3 CASES · 18 CLUES</span></div></section>
<main class="wrap game" id="workbench"><div class="section-head"><div><span class="kicker" id="caseTag">CASE FILE 01 / 03</span><h2 id="caseTitle"></h2></div><div class="progress"><strong id="score">0</strong> / 18<br>lines correctly routed</div></div><p class="context" id="context"></p><div class="desk"><section class="panel"><header><h3>The tangled function</h3><span>READ ONLY · investigate below</span></header><pre class="code" id="snippet"></pre><div class="cards" id="cards"></div></section><section class="panel"><header><h3>Two clean circuits</h3><span>YOUR REFACTOR</span></header><div class="lanes"><div class="lane"><h4 id="leftTitle"></h4><small id="leftHint"></small><ol id="leftItems"><li class="empty">Waiting for a clue…</li></ol></div><div class="lane"><h4 id="rightTitle"></h4><small id="rightHint"></small><ol id="rightItems"><li class="empty">Waiting for a clue…</li></ol></div></div><div class="controls"><button class="action" id="check">Run the tests ↗</button><button class="action secondary" id="next" hidden>Next case →</button><button class="action secondary" id="reset">Clear routes</button></div><p class="feedback" id="feedback" role="status" aria-live="polite">No clues routed yet. Take your time.</p><div class="insight" id="insight" hidden></div></section></div></main>
<footer class="footer"><div class="wrap"><p>Inspired by Jon's <a href="https://jona.ca/2016/01/code-smell-schizophrenic-method.html" target="_blank" rel="noopener noreferrer">Code smell: Schizophrenic method</a>.<br>Good code is not necessarily shorter. It knows what job it has.</p><p>Made with care by Chloe · <a href="index.php">Back to the collection</a></p></div></footer>
<script>
const cases=[
{title:'The parcel dispatcher',context:'A single dispatch() method handles both physical parcels and email notices. The if-statements are symptoms; the two workflows are the real boundary.',snippet:'function dispatch(order) {\n  if (order.type === "parcel") {\n    reserveShelf(order);\n    printShippingLabel(order);\n    handToCourier(order);\n  } else {\n    resolveEmailAddress(order);\n    renderNotice(order);\n    queueEmail(order);\n  }\n}',lanes:['Ship a parcel','Send a notice'],hints:['A physical thing leaves the building.','A message leaves the inbox.'],lines:[['reserveShelf(order)',0],['resolveEmailAddress(order)',1],['printShippingLabel(order)',0],['renderNotice(order)',1],['handToCourier(order)',0],['queueEmail(order)',1]],insight:'Instead of guarding every operation with a type check, give each workflow its own method. The caller can choose which one to use; neither method needs to know the other exists.'},
{title:'The festival ticket desk',context:'At the event entrance, the same function processes refunds and admits guests. Both touch a ticket, but they have different reasons to change.',snippet:'function handleTicket(ticket, mode) {\n  if (mode === "refund") {\n    verifyPurchase(ticket);\n    calculateRefund(ticket);\n    reversePayment(ticket);\n  } else {\n    checkGateWindow(ticket);\n    stampAdmission(ticket);\n    unlockTurnstile(ticket);\n  }\n}',lanes:['Refund a ticket','Admit a guest'],hints:['The money goes back.','The person goes in.'],lines:[['checkGateWindow(ticket)',1],['verifyPurchase(ticket)',0],['stampAdmission(ticket)',1],['calculateRefund(ticket)',0],['unlockTurnstile(ticket)',1],['reversePayment(ticket)',0]],insight:'The noun “ticket” is a red herring. Group operations by the reason they happen. A payment policy change should not send you digging through gate logic.'},
{title:'The greenhouse keeper',context:'This greenhouse robot waters plants and reports their health. They share sensors, but one changes the world and the other only describes it.',snippet:'function tend(bed, task) {\n  if (task === "water") {\n    readSoilMoisture(bed);\n    calculateWaterDose(bed);\n    openIrrigationValve(bed);\n  } else {\n    readLeafColour(bed);\n    buildHealthSummary(bed);\n    sendGardenerReport(bed);\n  }\n}',lanes:['Water the beds','Report their health'],hints:['Make a physical change.','Deliver an observation.'],lines:[['buildHealthSummary(bed)',1],['readSoilMoisture(bed)',0],['openIrrigationValve(bed)',0],['readLeafColour(bed)',1],['sendGardenerReport(bed)',1],['calculateWaterDose(bed)',0]],insight:'After the split, each method has one coherent outcome. Reading a sensor is not automatically “reporting”; its purpose depends on the workflow that uses it.'}
];
let round=0,route=Array(6).fill(null),locked=false,completed=0;
const el=id=>document.getElementById(id);
function render(){const c=cases[round];el('caseTag').textContent='CASE FILE '+String(round+1).padStart(2,'0')+' / 03';el('caseTitle').textContent=c.title;el('context').textContent=c.context;el('snippet').textContent=c.snippet;el('leftTitle').textContent='A · '+c.lanes[0];el('rightTitle').textContent='B · '+c.lanes[1];el('leftHint').textContent=c.hints[0];el('rightHint').textContent=c.hints[1];el('score').textContent=completed;el('cards').replaceChildren();c.lines.forEach(([line],i)=>{const card=document.createElement('div');card.className='card';card.id='card'+i;const code=document.createElement('code');code.textContent=line;const group=document.createElement('div');group.className='toggles';[0,1].forEach(side=>{const btn=document.createElement('button');btn.type='button';btn.dataset.side=side;btn.textContent=side?'B':'A';btn.setAttribute('aria-label','Route '+line+' to '+c.lanes[side]);btn.setAttribute('aria-pressed',String(route[i]===side));btn.classList.toggle('chosen',route[i]===side);btn.addEventListener('click',()=>{if(locked)return;route[i]=side;el('card'+i).classList.remove('wrong');updateRoutes();el('feedback').textContent='Route assigned. Keep going.'});group.append(btn)});card.append(code,group);el('cards').append(card)});updateRoutes();el('insight').hidden=true;el('next').hidden=true;el('check').hidden=false;el('reset').hidden=false;el('feedback').textContent='No clues routed yet. Take your time.'}
function updateRoutes(){const c=cases[round];[0,1].forEach(side=>{const list=el(side?'rightItems':'leftItems');list.replaceChildren();c.lines.forEach(([line],i)=>{if(route[i]===side){const li=document.createElement('li');li.textContent=line;list.append(li)}});if(!list.children.length){const li=document.createElement('li');li.className='empty';li.textContent='Waiting for a clue…';list.append(li)}});c.lines.forEach((_,i)=>{el('card'+i).querySelectorAll('button').forEach(b=>{const on=route[i]===Number(b.dataset.side);b.classList.toggle('chosen',on);b.setAttribute('aria-pressed',String(on))})})}
el('check').addEventListener('click',()=>{if(route.some(v=>v===null)){el('feedback').textContent='Route all six clues before running the tests.';return}const wrong=route.map((v,i)=>v!==cases[round].lines[i][1]?i:-1).filter(i=>i>=0);if(wrong.length){wrong.forEach(i=>el('card'+i).classList.add('wrong'));el('feedback').textContent=wrong.length+' '+(wrong.length===1?'clue needs':'clues need')+' another look. Ask: what outcome does this line serve?';return}locked=true;completed+=6;el('score').textContent=completed;cases[round].lines.forEach((_,i)=>el('card'+i).classList.add('correct'));el('insight').innerHTML='<strong>Tests green. A clean split!</strong><br>'+cases[round].insight;el('insight').hidden=false;el('check').hidden=true;el('reset').hidden=true;el('next').hidden=false;el('next').textContent=round===2?'Replay the cases ↺':'Next case →';el('feedback').textContent=round===2?'All 18 clues routed. You untangled every method.':'Case solved. Two jobs, two names, fewer surprises.'});
el('reset').addEventListener('click',()=>{route=Array(6).fill(null);render()});el('next').addEventListener('click',()=>{round=(round+1)%cases.length;if(round===0)completed=0;route=Array(6).fill(null);locked=false;render();el('workbench').scrollIntoView({behavior:'smooth',block:'start'})});render();
</script></body></html>